CREATE TYPE "SendStatus" AS ENUM ('ENVIADO','PENDENTE','ERRO','IGNORADO');
CREATE TYPE "LeapDayPolicy" AS ENUM ('FEB_28','MAR_01','ONLY_LEAP_YEAR');
CREATE TABLE "User" ("id" TEXT PRIMARY KEY,"name" TEXT,"email" TEXT NOT NULL UNIQUE,"passwordHash" TEXT NOT NULL,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Employee" ("id" TEXT PRIMARY KEY,"nome" TEXT NOT NULL,"email" TEXT UNIQUE,"dataNascimento" DATE NOT NULL,"area" TEXT,"equipe" TEXT,"cargo" TEXT,"telefone" TEXT,"ativo" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "BirthdaySend" ("id" TEXT PRIMARY KEY,"employeeId" TEXT NOT NULL REFERENCES "Employee"("id") ON DELETE CASCADE,"dataAniversario" DATE NOT NULL,"anoReferencia" INTEGER NOT NULL,"emailDestino" TEXT,"assunto" TEXT NOT NULL,"mensagem" TEXT NOT NULL,"status" "SendStatus" NOT NULL DEFAULT 'PENDENTE',"automatico" BOOLEAN NOT NULL DEFAULT true,"idempotencyKey" TEXT UNIQUE,"sentAt" TIMESTAMP(3),"errorMessage" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE "Settings" ("id" TEXT PRIMARY KEY DEFAULT 'singleton',"companyName" TEXT NOT NULL DEFAULT 'Line Haul',"teamName" TEXT NOT NULL DEFAULT 'Equipe Line Haul',"senderEmail" TEXT NOT NULL DEFAULT 'Aniversários <aniversarios@example.com>',"replyTo" TEXT,"sendTime" TEXT NOT NULL DEFAULT '09:00',"automaticEnabled" BOOLEAN NOT NULL DEFAULT false,"adminReminder" BOOLEAN NOT NULL DEFAULT false,"adminEmail" TEXT,"leapDayPolicy" "LeapDayPolicy" NOT NULL DEFAULT 'FEB_28',"subjectTemplate" TEXT NOT NULL DEFAULT '🎉 Feliz aniversário, {{nome}}!',"bodyTemplate" TEXT NOT NULL,"updatedAt" TIMESTAMP(3) NOT NULL);
CREATE TABLE "AuditLog" ("id" TEXT PRIMARY KEY,"action" TEXT NOT NULL,"entity" TEXT,"entityId" TEXT,"details" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX "Employee_ativo_idx" ON "Employee"("ativo");CREATE INDEX "BirthdaySend_status_createdAt_idx" ON "BirthdaySend"("status","createdAt");CREATE INDEX "AuditLog_createdAt_idx" ON "AuditLog"("createdAt");
